def readline(prev, filename=None, mode='r', trim=str.rstrip, start=1, end=sys.maxsize):



















    if prev is None:
        if filename is None:
            raise Exception('No input available for readline.')
        elif is_str_type(filename):
            file_list = [filename, ]
        else:
            file_list = filename
    else:
        file_list = prev

    for fn in file_list:
        if isinstance(fn, file_type):
            fd = fn
        else:
            fd = open(fn, mode)

        try:
            if start <= 1 and end == sys.maxsize:
                for line in fd:
                    yield trim(line)
            else:
                for line_no, line in enumerate(fd, 1):
                    if line_no < start:
                        continue
                    yield trim(line)
                    if line_no >= end:
                        break
        finally:
            if fd != fn:
                fd.close()

